def objects(g):
    bg=g[0][-1]; obs=[]
    for r in range(len(g)-4):
      for c in range(len(g[0])-4):
       b=g[r][c]
       if b in (2,8) and all(g[r][x]==b for x in range(c,c+5)) and all(g[x][c]==b for x in range(r,r+5)):
        if all(g[r+4][x]==b for x in range(c,c+5)) and all(g[x][c+4]==b for x in range(r,r+5)):
         obs.append((r,c,b,g[r+1][c+1]))
    return bg,obs

def transform(g):
    bg,obs=objects(g); out=[[bg]*len(g[0]) for _ in g]; placed=[]
    for r,c,b,inner in sorted(obs,key=lambda o:(o[0],o[1])):
        nc=0 if b==8 else len(g[0])-6
        def clash(x):
            return any(not (r+4<rr or rr+4<r or x+4<cc or cc+4<x) for rr,cc,_,_ in placed)
        while clash(nc): nc += 5 if b==8 else -5
        placed.append((r,nc,b,inner))
    for r,c,b,inner in placed:
        pat=[[b]*5]+[[b]+[inner]*3+[b] for _ in range(3)]+[[b]*5]
        for i in range(5): out[r+i][c:c+5]=pat[i]
    return out
